fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let nx = x.len();
    let ny = y.len();

    // Pre-allocate the output matrices
    let mut x_mat: Vec<Vec<f32>> = Vec::with_capacity(ny);
    let mut y_mat: Vec<Vec<f32>> = Vec::with_capacity(ny);

    // For each element of y, produce one row in each output
    for &yi in &y {
        // X row is just a copy of x
        x_mat.push(x.clone());
        // Y row is yi repeated nx times
        y_mat.push(vec![yi; nx]);
    }

    (x_mat, y_mat)
}

